  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page: #0d0f14;
  --bg-card: #161b27;
  --bg-card-hover: #1c2333;
  --bg-header: #1e2638;
  --border: #2a3347;
  --border-focus: #4a7cf7;
  --accent: #4a7cf7;
  --accent-glow: rgba(74, 124, 247, 0.18);
