  --text-secondary: #8892a4;
  --text-answer: #b0bac8;
  --radius: 12px;
  --transition: 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
  line-height: 1.6;
}

header {
  text-align: center;
  margin-bottom: 3rem;
}

header .cat-icon {
  font-size: 3.5rem;
  display: block;
  margin-bottom: 0.75rem;
  filter: drop-shadow(0 0 18px rgba(74, 124, 247, 0.5));
}

header h1 {
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #e8eaf0 30%, #4a7cf7 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

header p {
  margin-top: 0.6rem;
  color: var(--text-secondary);
  font-size: 1.05rem;
}

.faq-container {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* Each question/answer section */
.example {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.example:hover {
  border-color: #3a4a6a;
}

.example.open {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 1px var(--border-focus), 0 4px 24px var(--accent-glow);
}

/* Question trigger button */
.question-btn {
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.4rem;
  color: var(--text-primary);
  font-size: 1.02rem;
  font-weight: 600;
  text-align: left;
  transition: background var(--transition), color var(--transition);
}

.question-btn:hover {
  background: var(--bg-card-hover);
  color: #fff;
}

.example.open .question-btn {
  background: var(--bg-header);
  color: #fff;
  border-bottom: 1px solid var(--border);
}

.question-btn .q-label {
  color: var(--accent);
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  flex-shrink: 0;
  margin-right: 0.25rem;
}

.question-btn .q-text {
  flex: 1;
}

.chevron {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  color: var(--text-secondary);
  transition: transform var(--transition), color var(--transition);
}

.example.open .chevron {
  transform: rotate(180deg);
  color: var(--accent);
}

/* Collapsible answer container */
.details {
  overflow: hidden;
  max-height: 0;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.details-inner {
  padding: 1.1rem 1.4rem 1.3rem;
  color: var(--text-answer);
  font-size: 0.97rem;
  line-height: 1.75;
}

.details-inner strong {
  color: var(--text-primary);
}

.details-inner ul {
  margin-top: 0.5rem;
  padding-left: 1.3rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.details-inner ul li::marker {
  color: var(--accent);
}
