function createChevron() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 24 24");
  svg.setAttribute("fill", "none");
  svg.setAttribute("stroke", "currentColor");
  svg.setAttribute("stroke-width", "2.2");
  svg.setAttribute("stroke-linecap", "round");
  svg.setAttribute("stroke-linejoin", "round");
  svg.classList.add("chevron");
  const path = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
  path.setAttribute("points", "6 9 12 15 18 9");
  svg.appendChild(path);
  return svg;
}

function FAQItem({ question, answer, html }, index) {
  // .example wrapper
  const wrapper = document.createElement("div");
  wrapper.className = "example";

  // Button
  const btn = document.createElement("button");
  btn.className = "question-btn";
  btn.setAttribute("aria-expanded", "false");
  btn.setAttribute("aria-controls", `details-${index}`);
  btn.id = `question-${index}`;

  const label = document.createElement("span");
  label.className = "q-label";
  label.textContent = "Q";

  const text = document.createElement("span");
  text.className = "q-text";
  text.textContent = question;

  btn.appendChild(label);
  btn.appendChild(text);
  btn.appendChild(createChevron());
  wrapper.appendChild(btn);

  // .details collapsible container
  const details = document.createElement("div");
  details.className = "details";
  details.id = `details-${index}`;
  details.setAttribute("role", "region");
  details.setAttribute("aria-labelledby", `question-${index}`);

  const inner = document.createElement("div");
  inner.className = "details-inner";
  if (html) {
    inner.innerHTML = answer;
  } else {
    inner.innerHTML = answer; // answers may contain inline HTML tags like <strong>
  }
  details.appendChild(inner);
  wrapper.appendChild(details);

  // Toggle logic
  btn.addEventListener("click", () => {
    const isOpen = wrapper.classList.contains("open");

    // Close all others
    document.querySelectorAll(".example.open").forEach((el) => {
      el.classList.remove("open");
      el.querySelector(".question-btn").setAttribute("aria-expanded", "false");
      el.querySelector(".details").style.maxHeight = "0";
    });

    if (!isOpen) {
      wrapper.classList.add("open");
      btn.setAttribute("aria-expanded", "true");
      details.style.maxHeight = details.scrollHeight + "px";
    }
  });

  return wrapper;
}

function App() {
  const container = document.getElementById("faq-root");
  faqData.forEach((item, i) => {
    container.appendChild(FAQItem(item, i));
  });
}

document.addEventListener("DOMContentLoaded", App);
